
const products=[{id:1,name:'Cotton • Xanh lá thơm',type:'cotton',desc:'Cuộn mẫu 50g · Xanh sage',price:35000,color:'#829478',bg:'#e7ebdf',tag:'Một màu thật dịu'},{id:2,name:'Milk cotton • Hồng phấn',type:'milk',desc:'Cuộn mẫu 50g · Hồng pastel',price:25000,color:'#c69592',bg:'#f1e4df',tag:'Dành cho dự án nhỏ'},{id:3,name:'Cotton • Kem sữa',type:'cotton',desc:'Cuộn mẫu 50g · Kem tự nhiên',price:35000,color:'#d2bc92',bg:'#eee8db',tag:'Dễ phối màu'},{id:4,name:'Milk cotton • Xanh trời',type:'milk',desc:'Cuộn mẫu 50g · Xanh nhạt',price:25000,color:'#8baebc',bg:'#e4ecee',tag:''},{id:5,name:'Milk cotton • Nâu cacao',type:'milk',desc:'Cuộn mẫu 50g · Nâu ấm',price:25000,color:'#967460',bg:'#ece3da',tag:''},{id:6,name:'Kim móc cán gỗ',type:'tools',desc:'Dụng cụ mẫu · 3.0 mm',price:45000,color:'#ac8256',bg:'#e9e8df',tag:'Góc dụng cụ'}];
function ball(color,x=160,y=145,r=90){let lines='';for(let i=-7;i<=7;i++)lines+=`<path d="M ${x-r} ${y+i*12} Q ${x} ${y+i*8-r*.48} ${x+r} ${y+i*12+30}"/>`;return `<defs><clipPath id="b${x}${y}"><ellipse cx="${x}" cy="${y}" rx="${r}" ry="${r*.87}"/></clipPath><radialGradient id="g${x}${y}" cx="35%" cy="25%"><stop stop-color="${color}"/><stop offset="1" stop-color="${color}" stop-opacity=".8"/></radialGradient></defs><ellipse cx="${x}" cy="${y+r*.86}" rx="${r*.9}" ry="12" fill="#243e34" opacity=".1"/><ellipse cx="${x}" cy="${y}" rx="${r}" ry="${r*.87}" fill="url(#g${x}${y})"/><g clip-path="url(#b${x}${y})" stroke="#fff" stroke-opacity=".35" stroke-width="3" fill="none">${lines}</g><g clip-path="url(#b${x}${y})" stroke="#243e34" stroke-opacity=".14" stroke-width="2" fill="none" transform="rotate(68 ${x} ${y})">${lines}</g><path d="M${x+r*.8} ${y+r*.35} Q${x+r*1.4} ${y+r*1.3} ${x+r*.7} ${y+r*1.2}" fill="none" stroke="${color}" stroke-width="4"/>`}
function art(p){return `<svg viewBox="0 0 340 280" aria-hidden="true">${p.type==='tools'?'<g transform="rotate(30 170 140)"><rect x="153" y="100" width="34" height="142" rx="15" fill="#b58b61"/><path d="M170 105 V40 Q170 22 184 32 Q193 44 181 50" stroke="#88988d" stroke-width="12" fill="none" stroke-linecap="round"/></g>':ball(p.color,166,138,91)+'<rect x="120" y="99" width="90" height="77" rx="2" fill="#faf7ef"/><text x="165" y="130" text-anchor="middle" fill="#355747" font-family="Georgia" font-size="18">tiệm len</text><text x="165" y="153" text-anchor="middle" fill="#778170" font-family="Arial" font-size="9">MADE FOR YOUR IDEAS</text>'}</svg>`}
document.getElementById('heroArt').insertAdjacentHTML('afterbegin',`<svg viewBox="0 0 520 460" aria-hidden="true"><path d="M0 360 Q200 310 520 350 V460 H0" fill="#d7d1bc"/><g transform="rotate(-24 300 160)"><rect x="295" y="50" width="7" height="270" rx="3" fill="#ac8256"/><rect x="325" y="40" width="7" height="270" rx="3" fill="#ac8256"/></g>${ball('#c49b94',355,200,83)}${ball('#cfbd96',159,254,83)}${ball('#7f9271',279,305,100)}<rect x="224" y="263" width="110" height="82" fill="#f8f3e7" transform="rotate(-12 279 304)"/><text x="279" y="304" text-anchor="middle" font-family="Georgia" font-size="24" fill="#355747" transform="rotate(-12 279 304)">tiệm len</text></svg>`);
const shop=window.SHOP||{};const money=n=>n.toLocaleString('vi-VN')+' ₫';const $=id=>document.getElementById(id);let basket={};try{const saved=JSON.parse(localStorage.getItem('tiemlen-cart')||'{}');for(const p of products)if(Number.isInteger(saved?.[p.id])&&saved[p.id]>0&&saved[p.id]<=99)basket[p.id]=saved[p.id]}catch{}let filter='all',currentProduct=null;
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').style.display='none',3000)}
function render(){const q=$('search').value.trim().toLocaleLowerCase('vi');let shown=products.filter(p=>(filter==='all'||p.type===filter)&&(p.name+' '+p.desc).toLocaleLowerCase('vi').includes(q));if($('sort').value==='asc')shown.sort((a,b)=>a.price-b.price);if($('sort').value==='desc')shown.sort((a,b)=>b.price-a.price);$('products').innerHTML=shown.map(p=>`<article><button class="productart productvisual" data-detail="${p.id}" style="--bg:${p.bg}" aria-label="Xem chi tiết ${p.name}">${art(p)}${p.tag?`<span class="tag">${p.tag}</span>`:''}</button><div class="meta"><div><h3><button class="producttitle" data-detail="${p.id}">${p.name}</button></h3><p>${p.desc}</p></div><button class="add" data-add="${p.id}" aria-label="Thêm ${p.name} vào giỏ">+</button></div><div class="price">${money(p.price)}</div></article>`).join('')||'<p class="empty">Chưa tìm thấy sản phẩm. Thử một từ khóa khác nhé.</p>'}
function update(){try{localStorage.setItem('tiemlen-cart',JSON.stringify(basket))}catch{}$('count').textContent=Object.values(basket).reduce((a,b)=>a+b,0);$('cartItems').innerHTML=products.filter(p=>basket[p.id]).map(p=>`<div class="cartrow"><div>${p.name}<p class="help">${money(p.price)} / sản phẩm</p></div><div class="qty"><button data-change="${p.id}" data-delta="-1" aria-label="Giảm số lượng ${p.name}">−</button><span>${basket[p.id]}</span><button data-change="${p.id}" data-delta="1" aria-label="Tăng số lượng ${p.name}">+</button><button data-remove="${p.id}" aria-label="Xóa ${p.name}">×</button></div></div>`).join('')||'<p class="help">Giỏ hàng còn trống. Chọn một cuộn len bạn thích nhé.</p>';$('total').textContent=money(products.reduce((s,p)=>s+p.price*(basket[p.id]||0),0));$('copy').disabled=$('download').disabled=!Object.keys(basket).length;document.querySelectorAll('[data-order-channel]').forEach(b=>b.disabled=!Object.keys(basket).length)}
function add(id,n=1){const old=basket[id]||0;basket[id]=Math.min(99,old+n);update();toast(old+n>99?'Tối đa 99 sản phẩm mỗi loại.':'Đã thêm vào giỏ len ♡')}
function showDetail(id){const p=products.find(p=>p.id===Number(id));if(!p)return;currentProduct=p;$('detailContent').innerHTML=`<div class="detailgrid"><div class="productart" style="--bg:${p.bg}">${art(p)}</div><div><h2 id="detailTitle">${p.name}</h2><div class="price">${money(p.price)}</div><p>${p.type==='tools'?'Một chiếc kim cho những hàng móc nhỏ. Liên hệ tiệm để xác nhận kích thước và loại cán trước khi mua.':'Một màu sắc dành cho dự án thủ công của bạn. Tham khảo ảnh thực tế, thành phần sợi và cỡ kim với tiệm trước khi chọn.'}</p><dl><dt>Mã sản phẩm</dt><dd>TL-${String(p.id).padStart(3,'0')}</dd><dt>Loại</dt><dd>${p.type==='cotton'?'Cotton':p.type==='milk'?'Milk cotton':'Phụ kiện'}</dd><dt>Quy cách mẫu</dt><dd>${p.desc}</dd><dt>Tình trạng</dt><dd>Liên hệ xác nhận tồn kho</dd></dl><label class="help" for="detailQty">Số lượng</label><div class="detailactions"><input class="detailqty" id="detailQty" type="number" min="1" max="99" value="1" required><button class="primary" id="detailAdd">Thêm vào giỏ</button><button class="secondary" id="detailBuy">Liên hệ mua</button></div><p class="help">Màu minh họa có thể khác sản phẩm thật. Giá và quy cách hiện là dữ liệu mẫu.</p></div></div>`;$('detailAdd').onclick=()=>{const input=$('detailQty');if(!input.reportValidity()||!Number.isInteger(input.valueAsNumber))return;add(p.id,input.valueAsNumber)};$('detailBuy').onclick=()=>{const input=$('detailQty');if(!input.reportValidity()||!Number.isInteger(input.valueAsNumber))return;add(p.id,input.valueAsNumber);$('detail').close();$('cart').showModal()};$('detail').showModal()}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});render()});$('search').oninput=render;$('sort').onchange=render;$('products').onclick=e=>{const detail=e.target.closest('[data-detail]');if(detail)return showDetail(detail.dataset.detail);const b=e.target.closest('[data-add]');if(b)add(b.dataset.add)};$('openCart').onclick=()=>$('cart').showModal();$('closeCart').onclick=()=>$('cart').close();$('closeDetail').onclick=()=>$('detail').close();$('cartItems').onclick=e=>{const remove=e.target.closest('[data-remove]');if(remove){delete basket[remove.dataset.remove];return update()}const b=e.target.closest('[data-change]');if(!b)return;const id=b.dataset.change;basket[id]=Math.min(99,(basket[id]||0)+Number(b.dataset.delta));if(basket[id]<=0)delete basket[id];update()};
function order(){return `DANH SÁCH CHỌN HÀNG — ${shop.name||'Tiệm Len'}${shop.demo?' (BẢN MẪU)':''}\n`+products.filter(p=>basket[p.id]).map(p=>`TL-${String(p.id).padStart(3,'0')} | ${p.name} × ${basket[p.id]}: ${money(p.price*basket[p.id])}`).join('\n')+'\nTạm tính: '+$('total').textContent+'\nTên: '+($('buyerName').value.trim()||'Chưa cung cấp')+'\nLời nhắn: '+($('buyerNote').value.trim()||'Không có')+'\nVui lòng xác nhận tồn kho, phí giao hàng và cách thanh toán.'}
async function copyOrder(){try{await navigator.clipboard.writeText(order());toast('Đã sao chép. Dán danh sách vào cuộc trò chuyện với tiệm.');return true}catch{toast('Trình duyệt không cho sao chép. Hãy tải danh sách để gửi tiệm.');return false}}$('copy').onclick=copyOrder;$('download').onclick=()=>{const url=URL.createObjectURL(new Blob(['\uFEFF'+order()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='danh-sach-len.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('buyerForm').onsubmit=e=>e.preventDefault();
function channel(name,url,container,orderMode=false){const b=document.createElement(orderMode?'button':'a');b.className='secondary';b.textContent=name;if(orderMode){b.dataset.orderChannel=name;b.onclick=()=>{if(!Object.keys(basket).length)return;if(url.startsWith('mailto:')){window.location.href=url+'?subject='+encodeURIComponent('Hỏi mua len — '+(shop.name||'Tiệm Len'))+'&body='+encodeURIComponent(order())}else{const w=window.open(url,'_blank','noopener,noreferrer');copyOrder()}}}else{b.href=url;if(!url.startsWith('mailto:')&&!url.startsWith('tel:')){b.target='_blank';b.rel='noopener noreferrer'}}$(container).append(b)}
let channels=0;const zalo=String(shop.zaloPhone||'').replace(/[^0-9]/g,'');if(/^0\d{9}$/.test(zalo)){channel('Nhắn Zalo','https://zalo.me/'+zalo,'contactLinks');channel('Liên hệ qua Zalo','https://zalo.me/'+zalo,'orderChannels',true);channels++}let facebook;try{const u=new URL(shop.facebookUrl);if(u.protocol==='https:'&&['facebook.com','www.facebook.com','m.facebook.com','fb.com','www.fb.com','m.me'].includes(u.hostname))facebook=u.href}catch{}if(facebook){channel('Facebook của tiệm',facebook,'contactLinks');channel('Liên hệ qua Facebook',facebook,'orderChannels',true);channels++}if(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(shop.email||'')){channel('Email cho tiệm','mailto:'+shop.email,'contactLinks');channel('Soạn email hỏi mua','mailto:'+shop.email,'orderChannels',true);channels++}const phone=String(shop.phone||'').replace(/[^0-9+]/g,'');if(/^\+?\d{9,15}$/.test(phone)){channel('Gọi '+phone,'tel:'+phone,'contactLinks');channels++}$('contactStatus').textContent=channels?'Tiệm sẽ xác nhận sản phẩm và thông tin giao hàng qua kênh bạn chọn.':'Tiệm đang cập nhật thông tin liên hệ. Bạn có thể chọn len và lưu danh sách trước.';$('footerContact').textContent=channels?(shop.name+' · '+(phone||shop.email||'Liên hệ qua Zalo / Facebook')):'Thông tin shop đang được cập nhật.';if(shop.demo){const note=document.createElement('p');note.className='demo-note';note.textContent='Bản trưng bày mẫu: hình minh họa, sản phẩm và giá cần được shop cập nhật trước khi bán.';$('san-pham').insertBefore(note,$('san-pham').firstChild)}if(shop.name){document.title=shop.name+' • Một chút len, nhiều thương yêu';document.querySelector('.logo').lastChild.textContent=' '+shop.name}render();update();
